INSERT INTO public.eg_mdms_schema_definition (id, tenantid, code, description, definition, isactive, createdby, lastmodifiedby, createdtime, lastmodifiedtime) VALUES ('ff1582e5-f43b-4355-b3fc-65d231384a86', 'statea', 'tenant.masterschemavalidation', 'Tenant Master Schema - Used for Excel validation in Jupyter notebooks. Defines tenant information with ADMIN hierarchy (State/City levels)', '{"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["tenantDisplayName", "tenantCode", "tenantType", "logoFilePath"], "x-unique": ["tenantCode"], "properties": {"address": {"type": ["string", "null"], "maxLength": 500}, "latitude": {"type": ["number", "null"], "maximum": 90, "minimum": -90}, "longitude": {"type": ["number", "null"], "maximum": 180, "minimum": -180}, "admin0Name": {"type": ["string", "null"], "maxLength": 100}, "admin1Name": {"type": ["string", "null"], "maxLength": 100}, "admin2Name": {"type": ["string", "null"], "maxLength": 100}, "tenantCode": {"type": "string", "pattern": "^[A-Za-z]+\\.[A-Za-z]+$|^[A-Za-z]+$"}, "tenantType": {"enum": ["State", "City"], "type": "string"}, "logoFilePath": {"type": "string", "maxLength": 500, "minLength": 1}, "tenantWebsite": {"type": ["string", "null"]}, "tenantDisplayName": {"type": "string", "maxLength": 200, "minLength": 2}, "administrativeRegion": {"type": ["string", "null"], "maxLength": 200}}, "additionalProperties": false}', true, '9180cc27-b550-4245-96b1-e1e111e3eb3a', '9180cc27-b550-4245-96b1-e1e111e3eb3a', 1776662002560, 1776662002560) ON CONFLICT DO NOTHING;
INSERT INTO public.eg_mdms_schema_definition (id, tenantid, code, description, definition, isactive, createdby, lastmodifiedby, createdtime, lastmodifiedtime) VALUES ('cd0bf63d-41f5-4a66-aa9a-c8e8e8eae276', 'statea', 'common.masterschemavalidation', 'Common Master Schema - Used for Excel validation in Jupyter notebooks. Validates department, designation, complaint types with SLA resolution times', '{"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["departmentName", "designationName", "complaintType", "complaintSubType", "resolutionTimeHours"], "x-unique": ["complaintSubType"], "properties": {"searchWords": {"type": ["string", "null"], "pattern": "^[A-Za-z0-9_, &-]*$", "maxLength": 500, "description": "Comma-separated keywords (optional)"}, "complaintType": {"type": "string", "pattern": "^[A-Za-z0-9_ &-]+$", "maxLength": 100, "minLength": 2, "description": "Parent complaint category"}, "departmentName": {"type": "string", "maxLength": 100, "minLength": 2, "description": "Name of the government department"}, "designationName": {"type": "string", "maxLength": 100, "minLength": 2, "description": "Job title/position within the department"}, "complaintSubType": {"type": "string", "pattern": "^[A-Za-z0-9_ &-]+$", "maxLength": 100, "minLength": 2, "description": "Specific complaint sub-type (must be unique)"}, "resolutionTimeHours": {"type": "number", "maximum": 720, "minimum": 0.5, "description": "SLA hours for resolution"}}, "additionalProperties": false}', true, '9180cc27-b550-4245-96b1-e1e111e3eb3a', '9180cc27-b550-4245-96b1-e1e111e3eb3a', 1776662002589, 1776662002589) ON CONFLICT DO NOTHING;
INSERT INTO public.eg_mdms_schema_definition (id, tenantid, code, description, definition, isactive, createdby, lastmodifiedby, createdtime, lastmodifiedtime) VALUES ('7c5c1260-da4e-4810-8100-53b669587af4', 'statea', 'localization.masterschemavalidation', 'Localization Master Schema - Used for Excel validation in Jupyter notebooks. Validates multi-language translation data with locale codes (e.g., en_IN, hi_IN, ta_IN)', '{"type": "object", "$schema": "http://json-schema.org/draft-07/schema#", "required": ["module", "code", "locale"], "x-unique": ["code", "locale"], "properties": {"code": {"type": "string", "maxLength": 200, "minLength": 1, "description": "Translation key (e.g., PGR_COMPLAINT_TYPE, CORE_COMMON_SAVE)"}, "locale": {"type": "string", "pattern": "^[a-z]{2}_[A-Z]{2}$", "description": "Locale code in format: language_COUNTRY (e.g., en_IN, hi_IN, ta_IN)"}, "module": {"type": "string", "maxLength": 100, "minLength": 1, "description": "Module name (e.g., rainmaker-pgr, rainmaker-common)"}, "translation": {"type": ["string", "null"], "maxLength": 1000, "description": "Translated message in the specified locale"}, "englishMessage": {"type": ["string", "null"], "maxLength": 1000, "description": "English translation message"}}}', true, '9180cc27-b550-4245-96b1-e1e111e3eb3a', '9180cc27-b550-4245-96b1-e1e111e3eb3a', 1776662002635, 1776662002635) ON CONFLICT DO NOTHING;
